import{c as a,Q as r,j as e,m as d}from"./chunks/framework.DK3sgdKX.js";const _=JSON.parse('{"title":"PySTG 文档","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1779424456000}'),o={name:"index.md"};function h(n,t,i,l,s,b){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="pystg-文档" tabindex="-1">PySTG 文档 <a class="header-anchor" href="#pystg-文档" aria-label="Permalink to &quot;PySTG 文档&quot;">​</a></h1><p>Python + OpenGL 实现的东方 Project 风格弹幕射击游戏引擎。</p><p>引擎层提供高性能子弹池、激光、碰撞、渲染、音频； 内容层用 Python 协程编写关卡、波次、Boss 符卡； 两层通过 <code>StageContext</code> 桥接，互相解耦。</p><hr><h2 id="我是新手-从哪开始" tabindex="-1">我是新手，从哪开始？ <a class="header-anchor" href="#我是新手-从哪开始" aria-label="Permalink to &quot;我是新手，从哪开始？&quot;">​</a></h2><ol><li>先看 <a href="./getting-started">快速开始</a>：装环境、跑游戏、了解项目布局。</li><li>再看 <a href="./STAGE_SCRIPTING_GUIDE">弹幕脚本开发指南</a>：写第一张符卡。</li><li>想做杂兵就翻 <a href="./ENEMY_PRESET_SYSTEM">敌人预设系统</a>。</li><li>想用编辑器管理资产看 <a href="./EDITOR_TOOLS_GUIDE">编辑器工具</a>。</li></ol><hr><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><h3 id="给内容开发者-写关卡-弹幕-boss" tabindex="-1">给内容开发者（写关卡 / 弹幕 / Boss） <a class="header-anchor" href="#给内容开发者-写关卡-弹幕-boss" aria-label="Permalink to &quot;给内容开发者（写关卡 / 弹幕 / Boss）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./getting-started">快速开始</a></td><td>环境搭建、运行游戏、项目结构</td></tr><tr><td><a href="./STAGE_SCRIPTING_GUIDE">弹幕脚本开发指南</a></td><td>完整 API 参考 — 符卡、波次、敌人、Boss、激光、时停、标签</td></tr><tr><td><a href="./ENEMY_PRESET_SYSTEM">敌人预设系统</a></td><td>用 JSON 预设快速创建杂兵</td></tr><tr><td><a href="./EDITOR_TOOLS_GUIDE">编辑器工具</a></td><td>弹幕别名管理器、纹理编辑器、自机编辑器、对话立绘编辑器</td></tr></tbody></table><h3 id="给引擎开发者-修引擎-加新模块" tabindex="-1">给引擎开发者（修引擎 / 加新模块） <a class="header-anchor" href="#给引擎开发者-修引擎-加新模块" aria-label="Permalink to &quot;给引擎开发者（修引擎 / 加新模块）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./architecture">架构概览</a></td><td>引擎分层、模块依赖、核心数据流</td></tr><tr><td><a href="./TEXTURE_ASSET_SYSTEM">纹理资产系统</a></td><td>图集加载、精灵定义、动画配置</td></tr></tbody></table><hr><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>选型</th></tr></thead><tbody><tr><td>窗口 / 事件</td><td><strong>glfw</strong></td></tr><tr><td>渲染</td><td><strong>ModernGL</strong> + GLSL（实例化绘制）</td></tr><tr><td>子弹池</td><td><strong>NumPy</strong> 结构化数组 + <strong>Numba</strong> JIT</td></tr><tr><td>音频</td><td><strong>miniaudio</strong></td></tr><tr><td>字体</td><td><strong>freetype-py</strong>（位图字体）</td></tr><tr><td>关卡脚本</td><td>Python <code>async/await</code> 协程</td></tr><tr><td>编辑器 GUI</td><td><strong>PyQt5</strong></td></tr></tbody></table><hr><h2 id="仓库与版本" tabindex="-1">仓库与版本 <a class="header-anchor" href="#仓库与版本" aria-label="Permalink to &quot;仓库与版本&quot;">​</a></h2><ul><li>源码：<a href="https://github.com/qwqpap/PythonSTG" target="_blank" rel="noreferrer">github.com/qwqpap/PythonSTG</a></li><li>协议：<a href="https://github.com/qwqpap/PythonSTG/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a></li><li>资源版权：见仓库根目录 README 的&quot;资源版权&quot;说明</li></ul>',18)])])}const f=a(o,[["render",h]]);export{_ as __pageData,f as default};
